 const command=useCallback(async(body:any,success?:string)=>{if(busy)return null;setBusy(true);const signature=JSON.stringify(body),key=retryKeys.current[signature]??Array.from(crypto.getRandomValues(new Uint8Array(16)), x=>x.toString(16).padStart(2,'0')).join('');retryKeys.current[signature]=key;try{const r=await fetch('/api/commands',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':key,'x-saha-response':'delta',...paging(),...(orgRef.current?{'x-saha-organisation':orgRef.current}:{})},body:signature});const j:any=await r.json();if(!r.ok)throw Error(j.error);const next=j.snapshot??j.delta;if(orgRef.current!==next.organisation.id){setSelected(null);setVisitId(null);setView('organisation');setSearch('');setFilter('All programmes');openedRef.current=[];}orgRef.current=next.organisation.id;if(j.delta)setData((prev:any)=>prev&&prev.organisation.id===j.delta.organisation.id?mergeDelta(prev,j.delta,j.partition):j.delta);else setData(j.snapshot);delete retryKeys.current[signature];setError('');if(success)toast.success(success);if(next.patientPaging&&typeof j.result?.personId==='string'&&!next.people.some((p:Person)=>p.id===j.result.personId))void loadPatient(j.result.personId);return j.result;}catch(e){const message=e instanceof Error?e.message:'Action failed. Your input is still on screen.';toast.error(message);return null;}finally{setBusy(false)}},[busy]);
